// Verification harness for mss_contract.dart.
//
// Parses REAL API output (example_payload.json, generated by
// catalog/mss_api.py) and MSS_ANTIGRAVITY_HANDOFF/examples/*.json through
// every finalized model in frontend/lib/models/mss_contract.dart.
//
// Run:  dart verify_contract.dart

import 'dart:convert';
import 'dart:io';

import '../../../frontend/lib/models/mss_contract.dart';

int _checks = 0;
int _failures = 0;

void check(bool condition, String label) {
  _checks++;
  if (condition) {
    print('  PASS  $label');
  } else {
    _failures++;
    print('  FAIL  $label');
  }
}

void main() {
  final raw = File('example_payload.json').readAsStringSync();
  final resp = MSSSearchResponse.parse(raw);

  print('\n=== 1. MSSSearchResponse ===');
  check(resp.query.contains('collateral'), 'query parsed: "${resp.query}"');
  check(resp.detectedIntent.intents.contains('LOAN_REQUEST'), 'detectedIntent parsed');
  check(resp.detectedIntent.collateral.contains('collateral_free'),
      'collateral concept detected');
  check(resp.userProfile != null && resp.userProfile!.isNotEmpty,
      'userProfile echoed (${resp.userProfile})');
  check(resp.results.isNotEmpty, 'results parsed (${resp.results.length})');
  check(resp.metadata.catalogVersion != null, 'metadata.catalogVersion parsed');
  check(resp.deterministic, 'deterministic flag true');

  final r0 = resp.results.first;

  print('\n=== 2. SchemeResult ===');
  check(r0.schemeId.startsWith('SCH'), 'schemeId (${r0.schemeId})');
  check(r0.name.isNotEmpty, 'name');
  check(r0.status != SchemeStatus.unrecognised, 'status resolved (${r0.status.name})');
  check(r0.matchScore > 0, 'matchScore (${r0.matchScore})');
  check(r0.matchReasons.isNotEmpty, 'matchReasons (${r0.matchReasons.length})');
  check(r0.authority.isNotEmpty, 'authority resolved (${r0.authority.length})');
  check(r0.citations.isNotEmpty, 'citations resolved (${r0.citations.length})');
  check(r0.eligibility != null, 'eligibility attached');
  check(r0.applicationState != ApplicationState.unrecognised,
      'applicationState derived (${r0.applicationState.name})');
  check(r0.confidence != null, 'confidence (data-quality) present');
  final drift = (r0.rankingSignals.recomputedScore - r0.matchScore).abs();
  check(drift < 0.01, 'score reconstructible (drift ${drift.toStringAsFixed(5)})');

  print('\n=== 3. FinanceBenefit — decision 2 & nested collateral ===');
  final withAssistance =
      resp.results.where((r) => r.assistance.isNotEmpty).toList();
  check(withAssistance.isNotEmpty, 'assistance resolved on at least one result');
  if (withAssistance.isNotEmpty) {
    final fb = withAssistance.first.assistance.first;
    check(fb.type != null, 'type (${fb.type})');
    check(fb.amount.displayText != null || !fb.amount.hasAnyValue,
        'amount uses government text, not self-formatted numbers');
    check(fb.mode == null || fb.mode!.isNotEmpty, 'mode nullable-compatible (${fb.mode})');
    check(fb.conditions.isEmpty, 'conditions empty (0/115 coverage — expected)');
    check(fb.conditionsUnrecorded, 'conditionsUnrecorded distinguishes unrecorded from none');
    check(!fb.isCollateralFree || fb.collateralStatus == 'not_required',
        'isCollateralFree only when explicitly not_required');
  }

  // Test real nested collateral.status shape
  final nestedCollateralFb = FinanceBenefit.fromJson({
    'financeId': 'FIN000077',
    'type': 'loan',
    'collateral': {'status': 'not_required'},
  });
  check(nestedCollateralFb.collateralStatus == 'not_required',
      'FinanceBenefit parses real nested collateral.status shape');
  check(nestedCollateralFb.isCollateralFree, 'nested collateral isCollateralFree is true');

  print('\n=== 4. EligibilityMatch — decision 4 & 5 ===');
  final el = r0.eligibility!;
  check(el.schemeId == r0.schemeId, 'eligibility.schemeId matches result');
  check(el.excludedByAll.isEmpty || el.excludedByAll.isNotEmpty,
      'excludedByAll present as a list');
  check(el.eligible == el.excludedByAll.isEmpty,
      'eligible is consistent with excludedByAll');
  check(el.summary.isNotEmpty, 'honest summary: "${el.summary}"');
  final elJson = el.toJson();
  check(!elJson.containsKey('confidence'),
      'DECISION 5: no confidence field on EligibilityMatch');
  check(!elJson.containsKey('unmatchedCriteria'),
      'DECISION 4: no fabricated unmatchedCriteria field');

  final multi = EligibilityMatch.fromJson({
    'schemeId': 'SCH000003',
    'eligible': false,
    'matchedFacets': ['gender'],
    'neutralFacets': ['state'],
    'excludedByAll': ['enterpriseType', 'businessStage'],
    'excludedBy': 'enterpriseType',
  });
  check(multi.isExcludedOnMultipleCounts, 'multi-count exclusion detected');
  check(multi.excludedByAll.length == 2, 'both exclusions preserved');
  check(multi.summary.contains('enterpriseType') && multi.summary.contains('businessStage'),
      'summary names every exclusion');
  final legacy = EligibilityMatch.fromJson(
      {'schemeId': 'X', 'eligible': false, 'excludedBy': 'sector'});
  check(legacy.excludedByAll.length == 1, 'legacy excludedBy backfills excludedByAll');

  print('\n=== 5. Explanation — decision 6 ===');
  final exp = r0.explanation;
  check(exp.summary.isNotEmpty, 'summary built from result');
  check(exp.reasons.isNotEmpty, 'reasons carry the evidence');
  check(!exp.toJson().containsKey('evidence'),
      'DECISION 6: no evidence[] field — matchReasons IS the evidence');

  print('\n=== 6. Citation — decision 3 ===');
  final allCitations = resp.results.expand((r) => r.citations).toList();
  check(allCitations.isNotEmpty, 'citations present (${allCitations.length})');
  check(allCitations.any((c) => c.sourceName != null),
      'DECISION 3: sourceName populated from existing provenance');
  check(allCitations.any((c) => c.sourceTier != null),
      'DECISION 3: sourceTier populated from existing provenance');
  check(allCitations.every((c) => c.sourceTier == null || c.sourceTier == 2 || c.sourceTier == 5),
      'sourceTier only ever real policy tiers (2 or 5)');
  check(allCitations.any((c) => c.origin == CitationOrigin.schemeSource),
      'scheme_source origin preserved');
  final internal = allCitations.where((c) => !c.externalSource).toList();
  check(internal.every((c) => !c.isLiveOfficialFetch),
      'tier-2 internal fills never flagged as live official fetch');
  check(internal.every((c) => c.displayLabel.contains('no external source')),
      'internal fills labelled honestly, never a fabricated source name');

  print('\n=== 7. UpdateMetadata — decision 7 ===');
  final m = resp.metadata;
  check(m.catalogVersion != null, 'catalogVersion');
  check(m.lastUpdated != null, 'lastUpdated');
  check(m.catalogChecksum != null, 'catalogChecksum');
  check(m.entityCounts['scheme'] == 217, 'entityCounts.scheme == 217');
  check(!m.toJson().containsKey('availableUpdates'),
      'DECISION 7: no availableUpdates field');
  check(m.isStaleAgainst('old-tag'), 'isStaleAgainst detects a stale cache');
  check(!m.isStaleAgainst(m.catalogVersion), 'isStaleAgainst passes a current cache');
  check(m.zeroCoverageDimensions.contains('community'),
      'zero-coverage dimensions surfaced (${m.zeroCoverageDimensions})');

  print('\n=== 8. Real Handoff Payload: search_response.json ===');
  final handoffSearchFile = File('../../MSS_ANTIGRAVITY_HANDOFF/examples/search_response.json');
  if (handoffSearchFile.existsSync()) {
    final handoffSearchJson = jsonDecode(handoffSearchFile.readAsStringSync()) as Map<String, dynamic>;
    final handoffSearchResp = MSSSearchResponse.fromJson(handoffSearchJson);
    check(handoffSearchResp.results.isNotEmpty, 'real search_response.json parses results (${handoffSearchResp.results.length})');
    check(handoffSearchResp.query == 'women startup loan', 'query text extracted: ${handoffSearchResp.query}');
    check(handoffSearchResp.warnings.isNotEmpty, 'warnings extracted (${handoffSearchResp.warnings.length})');
  }

  print('\n=== 9. Real Handoff Payload: tamil_response.json ===');
  final handoffTamilFile = File('../../MSS_ANTIGRAVITY_HANDOFF/examples/tamil_response.json');
  if (handoffTamilFile.existsSync()) {
    final handoffTamilJson = jsonDecode(handoffTamilFile.readAsStringSync()) as Map<String, dynamic>;
    final handoffTamilResp = MSSSearchResponse.fromJson(handoffTamilJson);
    check(handoffTamilResp.results.isNotEmpty, 'real tamil_response.json parses results (${handoffTamilResp.results.length})');
  }

  print('\n=== round-trip (offline cache) ===');
  final rt = MSSSearchResponse.parse(resp.encode());
  check(rt.results.length == resp.results.length, 'result count survives');
  check(rt.results.first.schemeId == r0.schemeId, 'schemeId survives');
  check(rt.results.first.matchScore == r0.matchScore, 'score survives');
  check(rt.results.first.assistance.length == r0.assistance.length,
      'assistance survives');
  check(rt.results.first.authority.length == r0.authority.length,
      'authority survives');
  check(rt.results.first.citations.length == r0.citations.length,
      'citations survive');
  check(rt.results.first.eligibility?.excludedByAll.length ==
      r0.eligibility?.excludedByAll.length, 'excludedByAll survives');
  check(rt.metadata.catalogVersion == m.catalogVersion, 'catalogVersion survives');

  print('\n${'=' * 62}');
  print('$_checks checks, $_failures failure(s)');
  print('=' * 62);
  if (_failures > 0) exit(1);
}
